CREATE TABLE `User` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`name` VARCHAR(100) NOT NULL,`username` VARCHAR(40) NOT NULL,`email` VARCHAR(191) NOT NULL,`phone` VARCHAR(30) NOT NULL,`passwordHash` VARCHAR(255) NOT NULL,`role` ENUM('USER','ADMIN') NOT NULL DEFAULT 'USER',`status` ENUM('ACTIVE','DISABLED','SUSPENDED','BANNED') NOT NULL DEFAULT 'ACTIVE',`feePercent` DECIMAL(5,2) NOT NULL DEFAULT 0.70,`withdrawalFee` DECIMAL(18,2) NOT NULL DEFAULT 10000,`personalEnabled` BOOLEAN NOT NULL DEFAULT false,`webhookUrl` VARCHAR(2048) NULL,`webhookSecretHash` VARCHAR(128) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,UNIQUE KEY `User_username_key` (`username`),UNIQUE KEY `User_email_key` (`email`),UNIQUE KEY `User_phone_key` (`phone`),INDEX `User_status_createdAt_idx` (`status`,`createdAt`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Wallet` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`userId` INT UNSIGNED NOT NULL,`balance` DECIMAL(18,2) NOT NULL DEFAULT 0,`pending` DECIMAL(18,2) NOT NULL DEFAULT 0,UNIQUE KEY `Wallet_userId_key` (`userId`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `PaymentAccount` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`name` VARCHAR(100) NOT NULL,`owner` ENUM('ADMIN','USER') NOT NULL,`ownerUserId` INT UNSIGNED NULL,`type` ENUM('SHARED','PERSONAL') NOT NULL,`provider` VARCHAR(40) NOT NULL,`accountLabel` VARCHAR(191) NULL,`secretRef` VARCHAR(255) NULL,`status` ENUM('ACTIVE','INACTIVE','MAINTENANCE') NOT NULL DEFAULT 'ACTIVE',`priority` INT NOT NULL DEFAULT 100,`weight` INT NOT NULL DEFAULT 1,`lastUsedAt` DATETIME(3) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,INDEX `PaymentAccount_owner_type_status_priority_idx` (`owner`,`type`,`status`,`priority`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Payment` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`paymentId` VARCHAR(40) NOT NULL,`userId` INT UNSIGNED NOT NULL,`accountId` INT UNSIGNED NOT NULL,`reference` VARCHAR(191) NOT NULL,`amount` DECIMAL(18,2) NOT NULL,`uniqueCode` INT NOT NULL,`payableAmount` DECIMAL(18,2) NOT NULL,`feeAmount` DECIMAL(18,2) NOT NULL DEFAULT 0,`status` ENUM('PENDING','DETECTED','SUCCESS','EXPIRED','CANCELLED','LATE_REVIEW') NOT NULL DEFAULT 'PENDING',`providerRef` VARCHAR(191) NULL,`detectedAmount` DECIMAL(18,2) NULL,`detectedAt` DATETIME(3) NULL,`paidAt` DATETIME(3) NULL,`expiresAt` DATETIME(3) NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,UNIQUE KEY `Payment_paymentId_key` (`paymentId`),UNIQUE KEY `Payment_accountId_amount_uniqueCode_key` (`accountId`,`amount`,`uniqueCode`),INDEX `Payment_userId_status_createdAt_idx` (`userId`,`status`,`createdAt`),INDEX `Payment_accountId_status_expiresAt_idx` (`accountId`,`status`,`expiresAt`),INDEX `Payment_status_expiresAt_idx` (`status`,`expiresAt`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `WalletLedger` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`userId` INT UNSIGNED NOT NULL,`type` ENUM('CREDIT','DEBIT') NOT NULL,`reason` ENUM('PAYMENT','PAYMENT_FEE','WITHDRAWAL','WITHDRAWAL_FEE','REFUND','ADJUSTMENT') NOT NULL,`amount` DECIMAL(18,2) NOT NULL,`reference` VARCHAR(64) NOT NULL,`description` VARCHAR(255) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE KEY `WalletLedger_reference_key` (`reference`),INDEX `WalletLedger_userId_createdAt_idx` (`userId`,`createdAt`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `WithdrawalAccount` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`userId` INT UNSIGNED NOT NULL,`bankCode` VARCHAR(30) NOT NULL,`accountName` VARCHAR(100) NOT NULL,`accountNumber` VARCHAR(50) NOT NULL,`isDefault` BOOLEAN NOT NULL DEFAULT false,`verified` BOOLEAN NOT NULL DEFAULT false,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX `WithdrawalAccount_userId_idx` (`userId`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Withdrawal` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`withdrawalId` VARCHAR(40) NOT NULL,`userId` INT UNSIGNED NOT NULL,`accountId` INT UNSIGNED NOT NULL,`amount` DECIMAL(18,2) NOT NULL,`feeAmount` DECIMAL(18,2) NOT NULL,`netAmount` DECIMAL(18,2) NOT NULL,`status` ENUM('PENDING','PROCESSING','PAID','REJECTED','FAILED') NOT NULL DEFAULT 'PENDING',`providerRef` VARCHAR(191) NULL,`note` VARCHAR(255) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`processedAt` DATETIME(3) NULL,UNIQUE KEY `Withdrawal_withdrawalId_key` (`withdrawalId`),INDEX `Withdrawal_userId_status_createdAt_idx` (`userId`,`status`,`createdAt`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `ApiKey` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`userId` INT UNSIGNED NOT NULL,`name` VARCHAR(80) NOT NULL,`keyHash` VARCHAR(128) NOT NULL,`prefix` VARCHAR(20) NOT NULL,`active` BOOLEAN NOT NULL DEFAULT true,`lastUsedAt` DATETIME(3) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE KEY `ApiKey_keyHash_key` (`keyHash`),INDEX `ApiKey_userId_active_idx` (`userId`,`active`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Subscription` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`userId` INT UNSIGNED NOT NULL,`plan` VARCHAR(50) NOT NULL,`price` DECIMAL(18,2) NOT NULL,`status` ENUM('ACTIVE','EXPIRED','CANCELLED') NOT NULL DEFAULT 'ACTIVE',`startsAt` DATETIME(3) NOT NULL,`endsAt` DATETIME(3) NOT NULL,INDEX `Subscription_userId_status_endsAt_idx` (`userId`,`status`,`endsAt`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `PricingSetting` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`key` VARCHAR(80) NOT NULL,`value` VARCHAR(255) NOT NULL,`enabled` BOOLEAN NOT NULL DEFAULT true,`updatedAt` DATETIME(3) NOT NULL,UNIQUE KEY `PricingSetting_key_key` (`key`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `WebhookLog` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`userId` INT UNSIGNED NULL,`event` VARCHAR(80) NOT NULL,`target` VARCHAR(2048) NOT NULL,`status` INT NOT NULL,`response` TEXT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX `WebhookLog_userId_createdAt_idx` (`userId`,`createdAt`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `IdempotencyKey` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`userId` INT UNSIGNED NOT NULL,`key` VARCHAR(191) NOT NULL,`requestHash` VARCHAR(128) NOT NULL,`responseJson` TEXT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE KEY `IdempotencyKey_userId_key_key` (`userId`,`key`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `AuditLog` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`userId` INT UNSIGNED NULL,`action` VARCHAR(100) NOT NULL,`entity` VARCHAR(100) NULL,`entityId` VARCHAR(100) NULL,`ip` VARCHAR(64) NULL,`metadata` TEXT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX `AuditLog_userId_createdAt_idx` (`userId`,`createdAt`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `BotSession` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`jid` VARCHAR(191) NOT NULL,`userId` INT UNSIGNED NOT NULL,`tokenCiphertext` TEXT NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,UNIQUE KEY `BotSession_jid_key` (`jid`),INDEX `BotSession_userId_idx` (`userId`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `Wallet` ADD CONSTRAINT `Wallet_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `PaymentAccount` ADD CONSTRAINT `PaymentAccount_ownerUserId_fkey` FOREIGN KEY (`ownerUserId`) REFERENCES `User`(`id`) ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE `Payment` ADD CONSTRAINT `Payment_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `Payment` ADD CONSTRAINT `Payment_accountId_fkey` FOREIGN KEY (`accountId`) REFERENCES `PaymentAccount`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `WalletLedger` ADD CONSTRAINT `WalletLedger_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `WithdrawalAccount` ADD CONSTRAINT `WithdrawalAccount_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `Withdrawal` ADD CONSTRAINT `Withdrawal_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `Withdrawal` ADD CONSTRAINT `Withdrawal_accountId_fkey` FOREIGN KEY (`accountId`) REFERENCES `WithdrawalAccount`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `ApiKey` ADD CONSTRAINT `ApiKey_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `Subscription` ADD CONSTRAINT `Subscription_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `WebhookLog` ADD CONSTRAINT `WebhookLog_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE `IdempotencyKey` ADD CONSTRAINT `IdempotencyKey_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `AuditLog` ADD CONSTRAINT `AuditLog_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE `BotSession` ADD CONSTRAINT `BotSession_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
